        self.formula = problem.get("formula")
        self.equation = problem.get("equation")
        self.steps = problem.get("steps")

    def execute(self):
        # Initialize variables
        for var in self.steps:
            # Create variable
            var["name"]
            if "create_variable" in var:
                var["value"] = var["create_variable"]
            if "const_value" in var:
                var["value"] = var["const_value"]

            # Set values for equation based on variable's value
            if "set_value" in var:
                var["equation_value"] = var["set_value"]
            if "eqn" in var:
                if var["eqn"] != None:
                    # Requires solving the equation.
                    var["equation_value"] = self.solve_equation(var["name"], var["eqn"])

            # Print results of calculation
            print(f"{var['name']} = {var['value']}")

    def solve_equation(self, var_name, equation):
        # equation is dictionary with op and operands
