```rust
use std::collections::HashMap;
use std::collections::Hashable;

fn factorial(n: i32) -> i64 {
    if n == 0 {
        1
    } else {
        n as i64 * factorial(n - 1)
    }
}

fn factorial_vec_of_usize(vec: Vec<usize>) -> i64 {
    let mut res = 1;
    for i in vec {
        res *= i as i64;
    }
    res
}

fn count_russian_name_rearrangements(rus_name: Vec<char>) -> u128 {
    let mut map = std::collections::HashMap::<char, u128>::new();
    let mut res = 1u128;

    for x in rus_name {
        *map.entry(x).and_modify(|count| *count += 1).or_insert(0) += 1;
    }

    let mut keys = map.clone();
    let n: usize = rus_name.len();
    let mut vec: Vec<usize> = Vec::new();
    for (c, count) in keys {
        vec.push(count as usize);
    }
    for i in 0..n {
        if (vec[i] == 0).into() {
            res = res *!(n as u128);
            i += 1;
        } else {
            res *= factorial_vec_of_usize(vec.clone());
            vec[vec.len() - 1] -= 1;
            vec.remove(0);
        }
    }

    res
}

fn time_to_write_in_minutes(rus_name: &Vec<char>, per_minute: u128) -> u128 {
    let total_rearrangements = count_russian_name_rearrangements(rus_name.clone());
    if total_rearrangements == 0 {
        return 0;
    } else {
        let total_minutes = total_rearrangements as u128;
        return total_minutes / per_minute;
    }
}

fn time_to_write_in_hours(rus_name: &Vec<char>, per_minute: u128) -> f64 {
    let total_minutes = time_to_write_in_minutes(rus_name, per_minute);
    total_minutes as f64 / (60 as f64 * (per_minute as f64))
}

fn main() {
    let rus_name = "STEPHAN".chars().collect::<Vec<char>>();
    let per_minute = 12;
    let time_in_hours: f64 = time_to_write_in_hours(&rus_name, per_minute as u128);
    println!("Time to write all possible rearrangements of: {:?}", rus_name);
    println!("Time to write in minutes for per minute: {}", per_minute);
    println!("Time to write in hours: {:.2}", time_in_hours);
}
