#include <cmath>
#include <vector>
#include <algorithm>
#include <iostream>
#include <string>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <climits>

using namespace std;

// Function to calculate the power of a number
double power(double base, int exponent) {
  double result = 1.0;
  for (int i = 0; i < exponent; i++) {
    result = result * base;
  }
  return result;
}

// Function to calculate the binomial coefficient
int comb(int n, int k) {
  if (k > n - k) {
    k = n - k;
  }
  int res = 1;
  for (int j = 1; j <= k; j++) {
    res *= j;
  }
  int cnt = 1;
  for (int i = n; i >= (n-k); i--) {
    cnt *= i;
  }
  return res / cnt;
}

int main() {
        ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  const int totalTosses = 6;
  const double probabilityOfHead = 0.5;
  int permutationsWithTwoHeads = comb(totalTosses, 2); // Calculate the total number of ways to get exactly two heads
  double totalTossesProbability = power(probabilityOfHead, totalTosses); // Calculate the total probability of 6 tosses
  double probability = permutationsWithTwoHeads * totalTossesProbability; // Calculate the probability of getting exactly two heads
  for (int i = 0; i < 5; i++) {
    probability += permutationsWithTwoHeads * power(probabilityOfHead, totalTosses); // Calculate the additional probabilities for each fixed pair of heads
  }
  return 0;
}
```
